-- 1. Enable RLS on your target table
ALTER TABLE warehouse_orders ENABLE ROW LEVEL SECURITY;

-- 2. Force RLS for table owners to avoid accidental bypass in development
ALTER TABLE warehouse_orders FORCE ROW LEVEL SECURITY;

-- 3. Create a policy for selecting tenant rows
CREATE POLICY select_tenant_orders ON warehouse_orders
  FOR SELECT
  USING (
    org_id = NULLIF(current_setting('app.current_org_id', true), '')::uuid
  );

-- 4. Create a policy for inserting rows matching the tenant context
CREATE POLICY insert_tenant_orders ON warehouse_orders
  FOR INSERT
  WITH CHECK (
    org_id = NULLIF(current_setting('app.current_org_id', true), '')::uuid
  );
